import numpy as np


class FeasibleFirstMixedESv7:
    """
    Refinement of FeasibleFirstMixedESv6:
    - violation-greedy repair on the least-infeasible individual until feasibility,
    - rank-based parent selection with an archive-share that grows as the run progresses,
    - incumbent local search with single-coordinate moves followed by budget-capped
      random pair moves (escapes coordinate-wise local optima typical of integer designs),
    - success-adaptive restart strength, duplicate-evaluation cache (cached points cost no budget).
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        d = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        vt = [str(t) for t in func.variable_types]

        nv = np.ones(d, dtype=int)
        for i in range(d):
            if vt[i] != "continuous":
                nv[i] = int(func.n_values[i])

        cont = np.array([t == "continuous" for t in vt])
        disc = ~cont
        ordi = np.array([t == "ordinal" for t in vt])
        binm = np.array([t == "binary" for t in vt])
        cat = np.array([t == "categorical" for t in vt])
        span = np.where(cont, (ub - lb) / 2.0, 0.0)
        disc_idx = np.where(disc)[0]

        tau = 1.0 / np.sqrt(2.0 * np.sqrt(d))
        tau_d = 1.0 / np.sqrt(2.0 * d)
        pm_min = 1.0 / d
        pm_max = 0.5
        pm_default = min(0.5, max(pm_min, 1.5 / d))

        st = {"used": 0, "best_f": np.inf, "best_x": None, "best_ind": None}
        cache = {}
        archive = []
        strengths = [0.05, 0.2, 0.5]
        gain = [0.0, 0.0, 0.0]
        count = [1, 1, 1]

        def remaining():
            return self.budget - st["used"]

        def pf_now():
            frac = st["used"] / max(1, self.budget)
            return 0.45 * (1.0 - frac) + 0.05

        def archive_share():
            frac = st["used"] / max(1, self.budget)
            return 0.1 + 0.15 * frac

        def repair(x):
            x = np.array(x, dtype=float).copy()
            if cont.any():
                x[cont] = np.clip(x[cont], lb[cont], ub[cont])
            if disc.any():
                x[disc] = np.clip(np.round(x[disc]), 0, nv[disc] - 1)
            return x

        def hamming(a, b):
            return float(np.sum(np.abs(a - b) > 1e-12))

        def update_archive(ind):
            if ind["v"] != 0.0 or not np.isfinite(ind["f"]):
                return
            for a in archive:
                if a is ind or np.array_equal(a["x"], ind["x"]):
                    return
            archive.append(ind)
            archive.sort(key=lambda a: a["f"])
            if len(archive) > 12:
                keep = [archive[0]]
                rest = archive[1:]
                while len(keep) < 12 and rest:
                    sc = [min(hamming(r["x"], b["x"]) for b in keep) for r in rest]
                    keep.append(rest.pop(int(np.argmax(sc))))
                archive[:] = sorted(keep, key=lambda a: a["f"])

        def evaluate(x, s=0.2, pm=None):
            x = repair(x)
            k = x.tobytes()
            if k in cache:
                return cache[k]
            f, g = func(x)
            st["used"] += 1
            g = np.nan_to_num(np.asarray(g, dtype=float).ravel(),
                              nan=1e6, posinf=1e6, neginf=0.0)
            v = float(np.sum(np.maximum(g, 0.0)))
            f = float(f)
            if not np.isfinite(f):
                f = np.inf
                v += 1.0
            ind = {"x": x, "f": f, "v": v,
                   "s": s, "pm": pm_default if pm is None else pm}
            cache[k] = ind
            if v == 0.0 and f < st["best_f"]:
                st["best_f"] = f
                st["best_x"] = x.copy()
                st["best_ind"] = ind
            update_archive(ind)
            return ind

        def random_x():
            x = np.zeros(d)
            if cont.any():
                x[cont] = np.random.uniform(lb[cont], ub[cont])
            if disc.any():
                x[disc] = np.floor(np.random.rand(disc.sum()) * nv[disc])
            return x

        def key(ind):
            return (0, ind["f"]) if ind["v"] == 0.0 else (1, ind["v"])

        def stochastic_rank(pool):
            n = len(pool)
            idx = list(range(n))
            pf = pf_now()
            for _ in range(n):
                swapped = False
                for j in range(n - 1):
                    a = pool[idx[j]]
                    b = pool[idx[j + 1]]
                    if (a["v"] == 0.0 and b["v"] == 0.0) or np.random.rand() < pf:
                        bad = a["f"] > b["f"]
                    else:
                        bad = a["v"] > b["v"]
                    if bad:
                        idx[j], idx[j + 1] = idx[j + 1], idx[j]
                        swapped = True
                if not swapped:
                    break
            return [pool[i] for i in idx]

        def mutate(x, s, pm):
            x = np.array(x, dtype=float).copy()
            s = float(np.clip(s * np.exp(tau * np.random.randn()), 0.002, 0.5))
            pm = float(np.clip(pm * np.exp(tau_d * np.random.randn()), pm_min, pm_max))
            mask = np.random.rand(d) < pm
            if not mask.any():
                mask[np.random.randint(d)] = True
            m = mask & cont
            if m.any():
                x[m] += s * span[m] * np.random.randn(m.sum())
            for i in np.where(mask & ordi)[0]:
                if np.random.rand() < 0.7:
                    x[i] += np.random.choice([-1.0, 1.0])
                else:
                    x[i] = np.random.randint(nv[i])
            for i in np.where(mask & binm)[0]:
                x[i] = 1.0 - x[i]
            for i in np.where(mask & cat)[0]:
                if nv[i] > 1:
                    r = np.random.randint(nv[i] - 1)
                    xi = int(round(x[i]))
                    x[i] = r + 1 if r >= xi else r
            return x, s, pm

        def crossover(p1, p2):
            if np.random.rand() < 0.5:
                mask = np.random.rand(d) < 0.5
                x = np.where(mask, p1["x"], p2["x"])
            else:
                x = p1["x"].copy()
                w = np.random.rand()
                x[cont] = w * p1["x"][cont] + (1 - w) * p2["x"][cont]
                mask = np.random.rand(d) < 0.5
                x[disc & mask] = p2["x"][disc & mask]
            s = 0.5 * (p1["s"] + p2["s"])
            pm = 0.5 * (p1["pm"] + p2["pm"])
            return x, s, pm

        def tournament(pop):
            # rank-based binary tournament (pop is sorted best-first)
            i, j = np.random.randint(len(pop)), np.random.randint(len(pop))
            return pop[min(i, j)]

        def neighbour_moves(x, i):
            if cont[i]:
                sig = 0.03 * span[i]
                return [float(np.clip(x[i] + sig * np.random.randn(), lb[i], ub[i])),
                        float(np.clip(x[i] - sig * np.random.randn(), lb[i], ub[i]))]
            xi = int(round(x[i]))
            if binm[i]:
                return [1.0 - xi]
            if ordi[i]:
                c = []
                if xi + 1 < nv[i]:
                    c.append(xi + 1)
                if xi - 1 >= 0:
                    c.append(xi - 1)
                return c
            if cat[i]:
                others = [k for k in range(nv[i]) if k != xi]
                if len(others) > 4:
                    others = list(np.random.choice(others, 4, replace=False))
                return others
            return []

        def local_search(ind, cap):
            """Coordinate probing, then budget-capped random pair moves on discrete variables."""
            cur = ind
            used = 0
            improved = True
            while improved and used < cap and remaining() > 0:
                improved = False
                for i in np.random.permutation(d):
                    if used >= cap or remaining() <= 0:
                        break
                    for val in neighbour_moves(cur["x"], i):
                        if used >= cap or remaining() <= 0:
                            break
                        y = cur["x"].copy()
                        y[i] = val
                        cand = evaluate(y, cur["s"], cur["pm"])
                        used += 1
                        if key(cand) < key(cur):
                            cur = cand
                            improved = True
                            break
            # pair moves: change two discrete variables simultaneously
            if len(disc_idx) >= 2:
                tries = 0
                while used < cap and remaining() > 0 and tries < 3 * cap:
                    tries += 1
                    i, j = np.random.choice(disc_idx, 2, replace=False)
                    mi = neighbour_moves(cur["x"], i)
                    mj = neighbour_moves(cur["x"], j)
                    if not mi or not mj:
                        continue
                    y = cur["x"].copy()
                    y[i] = mi[np.random.randint(len(mi))]
                    y[j] = mj[np.random.randint(len(mj))]
                    cand = evaluate(y, cur["s"], cur["pm"])
                    used += 1
                    if key(cand) < key(cur):
                        cur = cand
            return cur

        def pick_restart_strength():
            ratios = [gain[k] / count[k] +
                      0.02 * np.sqrt(np.log(sum(count)) / count[k]) for k in range(3)]
            if np.random.rand() < 0.2:
                return np.random.randint(3)
            return int(np.argmax(ratios))

        # ---- initialisation ----
        mu = max(8, min(40, self.budget // 15))
        lam = 2 * mu

        pop = []
        tries = 0
        while len(pop) < mu and remaining() > 0 and tries < 50 * mu:
            pop.append(evaluate(random_x()))
            tries += 1
        pop.sort(key=key)

        last_best = st["best_f"]
        stagnation = 0
        ls_done_for = None

        while remaining() > 0 and pop:
            used_before = st["used"]
            children = []
            share = archive_share()
            for _ in range(lam):
                p1 = tournament(pop)
                if archive and np.random.rand() < share:
                    p2 = archive[np.random.randint(len(archive))]
                else:
                    p2 = tournament(pop)
                x, s, pm = crossover(p1, p2)
                if np.random.rand() < 0.05:
                    children.append((random_x(), 0.2, pm_default))
                else:
                    children.append(mutate(x, s, pm))

            new = []
            for x, s, pm in children:
                if remaining() <= 0:
                    break
                new.append(evaluate(x, s, pm))

            ranked = stochastic_rank(pop + new)
            pop = ranked[:mu]

            elite = st["best_ind"]
            if elite is not None and not any(p is elite for p in pop):
                pop[-1] = elite
                pop = sorted(pop, key=key)

            # local search on incumbent, or violation-greedy repair while infeasible
            if elite is not None and remaining() > 0 and ls_done_for != st["best_f"]:
                ls_done_for = st["best_f"]
                cap = min(5 * d + 8, remaining())
                better = local_search(elite, cap)
                if key(better) < key(elite):
                    pop = sorted(pop + [better], key=key)[:mu]
            elif elite is None and remaining() > 0:
                cap = min(2 * d + 2, remaining())
                base = pop[0]
                better = local_search(base, cap)
                if key(better) < key(base):
                    pop = sorted(pop + [better], key=key)[:mu]

            if st["best_f"] < last_best - 1e-12:
                last_best = st["best_f"]
                stagnation = 0
            else:
                stagnation += 1
            if st["used"] == used_before:
                stagnation += 5

            # archive-seeded, elite-centred restart with adaptive strength
            if stagnation > 6 and remaining() > 0 and st["best_ind"] is not None:
                elite = st["best_ind"]
                k_idx = pick_restart_strength()
                strength = strengths[k_idx]
                best_before = st["best_f"]

                seeds = [elite]
                if len(archive) > 1:
                    seeds.append(archive[np.random.randint(1, len(archive))])
                fresh = [elite]
                for _ in range(mu // 3):
                    if remaining() <= 0:
                        break
                    base = seeds[np.random.randint(len(seeds))]
                    x, s, pm = mutate(base["x"], strength, min(0.5, 3.0 / d))
                    fresh.append(evaluate(x, s, pm))
                for _ in range(mu // 4):
                    if remaining() <= 0:
                        break
                    fresh.append(evaluate(random_x()))
                guard = 0
                while len(fresh) < mu and remaining() > 0 and guard < 20 * mu:
                    x, s, pm = mutate(elite["x"], 0.3, 0.3)
                    fresh.append(evaluate(x, s, pm))
                    guard += 1

                feas_f = [ind["f"] for ind in fresh if ind["v"] == 0.0]
                g_val = 0.0
                if feas_f and np.isfinite(best_before):
                    g_val = max(0.0, best_before - min(feas_f)) / (abs(best_before) + 1.0)
                gain[k_idx] += g_val
                count[k_idx] += 1

                pop = sorted(fresh, key=key)[:mu]
                stagnation = 0

        return st["best_f"], st["best_x"]
